function makeWallet() {
  let balance = 0;
  return {
    add: (n) => { balance += n; },
    get: () => balance,
  };
}
const wallet = makeWallet();
wallet.add(5);
wallet.add(10);
console.log(wallet.get());

function makeCounter() {
  let count = 0; // new count on every call
  return () => ++count;
}
const a = makeCounter();
const b = makeCounter();
a(); a();
b(); // 1: b has its own count

